-- APN-MED — A nefrológiai-urológiai blokk kidolgozatlan kórképei.
--
-- A blokkban eddig tíz kidolgozott adatlap állt: krónikus vesebetegség, akut
-- vesekárosodás, húgyúti fertőzés, katéteres húgyúti fertőzés, vesekólika,
-- hyperkalaemia, akut vizeletretenció, diabéteszes vesebetegség, jóindulatú
-- prosztata-megnagyobbodás és vérvizelés. A többi tétel „tartalom fejlesztés
-- alatt" jelöléssel szerepelt.
--
-- Ez a migráció 11 kórképet tölt fel, az eddigi tematika szerint, friss
-- irányelvekre hivatkozva. A források a 0082 óta működő átvezetés révén
-- automatikusan megjelennek a Tudástár irányelvjegyzékében is.
--
-- ══ A duplikáció elkerülése ══════════════════════════════
--
-- A csonkok a katalógus-importból származnak, nem migrációból, ezért az
-- azonosítójuk nem ismert előre. Ha vakon beszúrnánk, a vérlemezke-gátlók
-- esete ismétlődne: két sor keletkezne ugyanarra a kórképre, eltérő
-- azonosítóval.
--
-- Ezért a migráció két lépésben dolgozik:
--   1. a meglévő CSONKOT tölti fel, ha a neve vagy valamelyik rokon neve
--      egyezik — az azonosítója és a rá mutató hivatkozások megmaradnak;
--   2. csak azt szúrja be újként, amihez nem talált meglévő sort.
--
-- Kidolgozott adatlapot nem ír felül: a feltöltés feltétele az is_stub.

-- ══ 0. Névegyeztető segédfüggvény ════════════════════════
create or replace function public.nev_norm(t text)
returns text language sql immutable as $$
  select lower(regexp_replace(coalesce(t, ''), '[^[:alnum:]]', '', 'g'))
$$;

-- ══ 1. Mi van most a blokkban? ═══════════════════════════
select
  case when is_stub then 'fejlesztés alatt' else 'kidolgozott' end as allapot,
  count(*) as darab,
  string_agg(name, ', ' order by name) as korkepek
from public.diseases
where status = 'published' and specialty = 'Nefrológia-urológia'
group by 1;

-- ══ 2. Az új tartalom ════════════════════════════════════
create temporary table uj_korkepek (
  slug text, name text, aliases text[], abbrev text,
  score_ids text[], lab_ids text[], ekg_ids text[],
  guideline_kw text[], body jsonb, match_names text[]
) on commit drop;

insert into uj_korkepek values
    ('nephrosis-szindroma', 'Nephrosis szindróma', '{"nephrotikus szindróma","nagy fehérjevizelés","ödémás vesebetegség"}'::text[], 'Nephrosis',
     '{"news2"}'::text[], '{"uprot","krea","egfr","na","k","ldl","hb","ca"}'::text[], '{}'::text[],
     '{"nephrosis","fehérjevizelés","proteinuria","ödéma"}'::text[], '{"brief_what":"A vese szűrőegységeinek károsodása miatt nagy mennyiségű fehérje ürül a vizelettel. Ennek következménye a vér fehérjeszintjének csökkenése, a kiterjedt ödéma és a vérzsírok emelkedése.","brief_why":"Az ödémát gyakran szívelégtelenségnek tartják, és vízhajtóval kezelik anélkül, hogy a vizeletet megnézték volna. Egy vizeletcsík mindent eldönt. A másik, kevésbé ismert veszély a fokozott véralvadékonyság: a fehérjevesztéssel a véralvadást gátló fehérjék is elvesznek, és a trombózis a szindróma egyik leggyakoribb szövődménye.","when":["Gyorsan kialakuló, kiterjedt ödéma — szemhéjon, lábszáron, hasfalon","Habzó vizelet","Hirtelen testsúlynövekedés folyadékvisszatartásból","Fáradtság, étvágytalanság","Vizeletvizsgálaton kimutatott nagy fehérjevizelés"],"examine":["Az ödéma kiterjedése és jellege: a nephrosis ödémája reggel az arcon, a szemhéjon is jelentkezik — ez elkülöníti a szívelégtelenség jellemzően alsó végtagi ödémájától","Napi testsúlymérés: a folyadékállapot változását ez mutatja a legmegbízhatóbban","Vérnyomás és a folyadékállapot együttes megítélése","Hasi folyadékgyülem keresése","Légzésszám és oxigéntelítettség: mellkasi folyadékgyülem alakulhat ki","Alsó végtagi duzzanat aszimmetriája — mélyvénás trombózis irányába"],"labs":"A vizelet fehérje/kreatinin vagy albumin/kreatinin aránya a kórisme alapja; a vizeletcsík fehérjejelzése irányt ad, de mennyiséget nem. Szérum albumin, vesefunkció, ionok, vérzsírok. A kiváltó ok keresése célzott vizsgálatokkal: cukorbetegség, immunológiai eltérések, fertőzések, vérképzőszervi betegség.","ekg":"Nem a kórkép része; ioneltérés gyanújánál indokolt.","imaging":"Vese-ultrahang a szerkezeti ok tisztázására. Vesebiopszia felnőttkorban a legtöbb esetben szükséges, mert a kezelés a szövettani formától függ. Trombózis gyanújánál célzott érvizsgálat.","scores":"Külön pontozó nincs. A NEWS2 az általános állapot követésére alkalmas. A fehérjevizelés mértéke és a szűrési érték együtt adja a kockázat megítélését.","red_flags":["Hirtelen romló vesefunkció","Egyoldali lábszárduzzanat, mellkasi fájdalom, nehézlégzés — trombózis vagy tüdőembólia","Ágyéki fájdalom vérvizeléssel — vesevéna-trombózis","Láz, hasi fájdalom — a fehérjevesztéssel az ellenállóképesség is csökken, a hashártyagyulladás valós kockázat","Súlyos ödéma légzési nehezítettséggel","Csökkenő vizeletmennyiség"],"apn_focus":["Az ödéma kivizsgálásánál a vizeletvizsgálat elhagyhatatlan: a nephrosis évekig szívelégtelenségként kezelt beteg sem ritka","Napi testsúly és folyadékegyenleg vezetése — a vízhajtó hatásának megítélése ezen alapul, nem a szemrevételezésen","A trombózis jeleinek keresése minden vizitnél: az aszimmetrikus lábszárduzzanat a kiterjedt ödéma mellett könnyen elsikkad","A fertőzésre való fogékonyság ismertetése a beteggel: láz esetén késedelem nélkül jelentkezzen","Sóbevitel csökkentésének megtanítása — az ödéma kezelésében ez a vízhajtóval egyenrangú lépés","A bőr ápolása: a feszülő, ödémás bőr könnyen sérül és nehezen gyógyul","Az immunológiai kezelés melletti mellékhatások és fertőzésjelek követése"],"treatment":["A kiváltó szövettani forma szerinti célzott kezelés — ezt a vesebiopszia dönti el","Az ödéma kezelése vízhajtóval, sószegény étrenddel","A fehérjevizelés csökkentése a vese-védő gyógyszerekkel","A vérzsírok kezelése","A trombózis megelőzése súlyos, tartós fehérjevesztésnél — az indikáció egyéni mérlegelés kérdése","A fertőzések időben történő kezelése"],"followup":["A fehérjevizelés és a vesefunkció rendszeres ellenőrzése — a kezelés hatását ez mutatja","Testsúly, vérnyomás és ödéma otthoni követése","A szövődmények szűrése: trombózis, fertőzés, alultápláltság","Az immunológiai kezelés melletti rendszeres laborellenőrzés","Oltási állapot rendezése, ha a kezelés az immunrendszert érinti"],"source_name":"KDIGO irányelv a glomeruláris betegségek kezeléséről","source_url":"https://kdigo.org/guidelines/gd/","version":"2021","updated":"2026-09-22","evidence":"A felnőttkori nephrosis szindróma kezelése szövettani formánként eltér, ezért a biopszia a legtöbb esetben indokolt. A trombózis-megelőzés rutinszerű alkalmazása nem javasolt: egyéni kockázatbecslésen alapul. A gyermekkori formára a KDIGO 2025-ben önálló irányelvet adott ki, amely a felnőttekre nem vonatkozik."}'::jsonb,
     '{"Nephrosis szindróma","nephrotikus szindróma","nagy fehérjevizelés","ödémás vesebetegség"}'::text[]),
    ('glomerulonephritis', 'Glomerulonephritis (nephritis szindróma)', '{"vesegyulladás","nephritis szindróma","glomerulusbetegség"}'::text[], 'GN',
     '{"news2"}'::text[], '{"krea","egfr","uprot","used","k","crp","hb","ana"}'::text[], '{"hyperk"}'::text[],
     '{"glomerulonephritis","nephritis","vérvizelés","vesegyulladás"}'::text[], '{"brief_what":"A vese szűrőegységeinek gyulladásos betegsége. Jellemzője a vérvizelés, a fehérjevizelés, a magas vérnyomás és a romló vesefunkció együttes megjelenése.","brief_why":"A gyorsan romló formánál hetek döntenek: a késedelem visszafordíthatatlan vesekárosodást okoz. A felismerés kulcsa egy olcsó vizsgálat — a vizeletüledék —, amit épp ilyenkor szokás elhagyni. A torzult alakú vörösvérsejt és a vörösvérsejt-cilinder a vese eredetét bizonyítja, és elkülöníti a húgyúti vérzéstől.","when":["Barnás, kólaszínű vizelet","Ödéma, magas vérnyomás és vérvizelés együtt","Romló vesefunkció ismert ok nélkül","Felső légúti fertőzés vagy bőrfertőzés után néhány nappal-héttel jelentkező vizelettünet","Ízületi panasz, bőrtünet, véres köpet a vesetünetek mellett — rendszerbetegség irányába"],"examine":["Vérnyomás mérése — a magas érték a nephritis szindróma része, nem véletlen egybeesés","Ödéma keresése, jellemzően az arcon és a szemhéjon is","Vizeletmennyiség és -szín követése","Bőrtünetek: pontszerű bevérzések, tapintható kiütés","Ízületi panasz, izomfájdalom","Légzőszervi tünetek: véres köpet — a tüdő és a vese együttes érintettsége sürgős állapot"],"labs":"A vizeletüledék a kórkép legfontosabb vizsgálata: a torzult alakú vörösvérsejt és a vörösvérsejt-cilinder vese eredetű vérzést bizonyít. Mellette fehérjevizelés mennyisége, vesefunkció, ionok, vérkép, gyulladásos értékek. Immunológiai vizsgálatok a forma tisztázására. A minta gyors feldolgozása fontos: a cilinderek állás közben szétesnek.","ekg":"Magas káliumszint gyanújánál indokolt, mert a romló vesefunkció mellett ez gyorsan kialakul.","imaging":"Vese-ultrahang a méret és a szerkezet megítélésére, egyben a kőbetegség és az elzáródás kizárására. Vesebiopszia a forma tisztázására — a kezelés ezen múlik.","scores":"Külön pontozó nincs. A szűrési érték változásának üteme a legfontosabb mutató: a hetek alatti romlás gyorsan előrehaladó formára utal.","red_flags":["Napok-hetek alatt romló vesefunkció — gyorsan előrehaladó glomerulonephritis, sürgős nefrológiai ellátás","Véres köpet vagy nehézlégzés a vesetünetek mellett — tüdő- és veseérintettség együtt","Magas káliumszint EKG-eltéréssel","Csökkenő vizeletmennyiség","Kezelhetetlen magas vérnyomás","Tudatzavar, görcs — magas vérnyomás okozta agyi érintettség"],"apn_focus":["A vizeletüledék kérése és a minta gyors továbbítása: a cilinderek órák alatt szétesnek, és ezzel a legfontosabb információ vész el","A vérnyomás és a vizeletmennyiség rendszeres, dokumentált mérése — a romlás üteme ebből látszik","A gyorsan romló forma gyanújának azonnali jelzése: itt hetek döntenek a maradandó károsodásról","A vérvizelés forrásának elkülönítése: a húgyúti eredetű vérzés fájdalommal, rögökkel jár, a vese eredetű jellemzően nem","Az immunszuppresszív kezelés melletti fertőzésjelek figyelése és oktatása","A beteg tájékoztatása: a vizelet színének változása követendő, de a vesefunkció romlása ettől függetlenül is zajlik"],"treatment":["A kezelés a szövettani forma szerint történik — a biopszia nélküli kezelés kivételes","A gyulladás csökkentése immunszuppresszív kezeléssel a súlyos formáknál","Vérnyomáscsökkentés vese-védő szerekkel","A folyadék- és sóháztartás rendezése","A fertőzéses kiváltó ok kezelése, ha van","Vesepótló kezelés súlyos, akut vesekárosodás mellett"],"followup":["Vesefunkció és fehérjevizelés rendszeres követése — a visszaesés hónapokkal a kezelés után is jöhet","Vérnyomás otthoni mérése","Az immunszuppresszív kezelés mellékhatásainak szűrése","Oltási állapot rendezése","Hosszú távú nefrológiai gondozás: a lezajlott gyulladás után is maradhat krónikus vesebetegség"],"source_name":"KDIGO irányelv a glomeruláris betegségek kezeléséről","source_url":"https://kdigo.org/guidelines/gd/","version":"2021","updated":"2026-09-22","evidence":"A vizeletüledék vizsgálata a kórisme alapja, és a gyorsan előrehaladó forma korai felismerése bizonyítottan javítja a vesetúlélést. Az ANCA-asszociált vasculitisre és az IgA-nefropátiára a KDIGO önálló, frissebb irányelveket adott ki."}'::jsonb,
     '{"Glomerulonephritis (nephritis szindróma)","vesegyulladás","nephritis szindróma","glomerulusbetegség"}'::text[]),
    ('adpkd', 'Policisztás vesebetegség (ADPKD)', '{"ADPKD","policisztás vese","cisztás vesebetegség","öröklődő vesebetegség"}'::text[], 'ADPKD',
     '{"news2"}'::text[], '{"krea","egfr","na","k","used","hb"}'::text[], '{}'::text[],
     '{"policisztás","ADPKD","ciszta","öröklődő vesebetegség"}'::text[], '{"brief_what":"Öröklődő betegség, amelyben a vesékben folyadékkal telt ciszták képződnek és növekednek. A ciszták fokozatosan kiszorítják a működő veseszövetet, és a vesefunkció évtizedek alatt romlik.","brief_why":"A leggyakoribb örökletes vesebetegség, és a felnőttkori vesepótló kezelések jelentős részéért felel. 2025-ben kapta meg az első önálló nemzetközi irányelvét. Ami az ápolói munkában a legfontosabb: a betegség családi, ezért a felismerés a rokonok szűrését is elindítja — és a gyermekek szűrésének kérdése érzékeny döntés, nem automatizmus.","when":["Családban előforduló vesebetegség vagy vesepótló kezelés","Ismétlődő ágyéki fájdalom","Vérvizelés","Fiatal felnőttkorban induló magas vérnyomás — gyakran ez az első jel","Véletlenül talált vesecisztaság képalkotáson","Ismétlődő húgyúti fertőzés vagy kőbetegség"],"examine":["Vérnyomás mérése: a magas vérnyomás gyakran a vesefunkció romlása előtt évekkel megjelenik","A has tapintása: előrehaladott állapotban a megnagyobbodott vesék tapinthatók","Fájdalom jellegének tisztázása: a ciszta bevérzése, a fertőzött ciszta és a kő eltérő ellátást igényel","Családfa felvétele — ez irányítja a rokonok szűrését","Testsúly és haskörfogat: a nagy vesék teltségérzést, étvágycsökkenést okoznak"],"labs":"Vesefunkció és ionok rendszeresen. Vizeletvizsgálat vérvizelés és fertőzés irányában. Vérkép: a cisztás vese tovább termelhet vörösvérsejt-serkentő hormont, ezért a vérszegénység később jelentkezik, mint más vesebetegségnél — ez tévesen megnyugtató lehet.","ekg":"Nem a kórkép része.","imaging":"Ultrahang a kórisme alapja; a ciszták száma és az életkor együtt dönt. A vesetérfogat mágneses vizsgálattal mért értéke a romlás ütemének legjobb előrejelzője, és a célzott gyógyszeres kezelés indikációjához is ezt használják. Agyi érfestés nem rutinszerű: családi előfordulás vagy panasz esetén mérlegelendő.","scores":"A vesetérfogaton és az életkoron alapuló besorolás adja meg a gyors romlás kockázatát — ez dönti el, kinél indokolt a célzott gyógyszeres kezelés.","red_flags":["Hirtelen, erős fejfájás — agyi érdudor szakadásának gyanúja, azonnali ellátás","Láz ágyéki fájdalommal — fertőzött ciszta, a szokásos antibiotikumok egy része nem jut be a cisztába","Tartós, erős ágyéki fájdalom vérvizeléssel — ciszta bevérzése","Gyorsan romló vesefunkció","Kezelhetetlen magas vérnyomás","Hasi terime hirtelen növekedése"],"apn_focus":["A vérnyomás szoros kezelése a legfontosabb beavatkozás: a jól beállított vérnyomás lassítja a romlást, és csökkenti a szív- és érrendszeri kockázatot","Bőséges folyadékbevitel támogatása — a ciszták növekedésére kedvezően hat, és a kőképződést is csökkenti","A célzott gyógyszeres kezelés melletti oktatás: a szer jelentős vizeletürítés-fokozódást okoz, ami a mindennapokat átalakítja, és májenzim-ellenőrzést igényel","Sószegény étrend megtanítása","A családi vonatkozás kezelése: a rokonok tájékoztatása fontos, a gyermekek szűrése viszont mérlegelendő döntés — a tünetmentes gyermek korai kórisméje életbiztosítási és lelki következményekkel jár","A fájdalom hátterének tisztázása minden alkalommal: a rutinszerű fájdalomcsillapítás elfedheti a fertőzött cisztát","A vesekárosító gyulladáscsökkentők kerülésének oktatása"],"treatment":["Vérnyomáscsökkentés vese-védő szerekkel, szoros célértékkel","Célzott gyógyszeres kezelés a gyors romlás kockázatával rendelkező betegeknél","Bő folyadékbevitel és sószegény étrend","A szövődmények kezelése: fertőzött ciszta célzott antibiotikummal, kő, vérzés","Fájdalomcsillapítás a vesét kímélő szerekkel","Vesepótló kezelés vagy átültetés előkészítése a végstádium közeledtével"],"followup":["Vesefunkció és vérnyomás rendszeres ellenőrzése","A célzott kezelés melletti májenzim- és folyadékállapot-követés","Képalkotó ellenőrzés a romlás ütemének megítélésére","A család tájékoztatása és a felnőtt rokonok szűrésének felajánlása","A vesepótló kezelés időben történő előkészítése"],"source_name":"KDIGO 2025 irányelv a policisztás vesebetegség ellátásáról","source_url":"https://kdigo.org/guidelines/autosomal-dominant-polycystic-kidney-disease-adpkd/","version":"2025","updated":"2026-09-22","evidence":"Az első önálló nemzetközi irányelv a betegségről. A vesetérfogat alapú kockázatbecslés és a célzott gyógyszeres kezelés indikációja a legfontosabb újdonsága. A tünetmentes gyermekek szűrését az irányelv nem javasolja rutinszerűen."}'::jsonb,
     '{"Policisztás vesebetegség (ADPKD)","ADPKD","policisztás vese","cisztás vesebetegség","öröklődő vesebetegség"}'::text[]),
    ('dialisis-gondozas', 'Vesepótló kezelés (dialízis) gondozása', '{"dialízis","művese","hemodialízis","peritoneális dialízis","vesepótló kezelés"}'::text[], 'Dialízis',
     '{"news2","must"}'::text[], '{"krea","egfr","k","na","ca","phos","hb","ferr","tsat","crp"}'::text[], '{"hyperk"}'::text[],
     '{"dialízis","vesepótló kezelés","shunt","peritoneális"}'::text[], '{"brief_what":"A végstádiumú vesebetegség kezelése, amelyben gép vagy a hasüreg hártyája veszi át a vese méregtelenítő és folyadékeltávolító szerepét. Két fő formája a gépi vérkezelés és a hasi forma.","brief_why":"A dializált beteg nemcsak a dialízis központban jelenik meg: kórházi osztályon, háziorvosnál, sürgősségi ellátásban is találkozunk vele, és ilyenkor a legtöbb hiba a nem dialízis szakmájú ellátásban történik. A shuntos kar védelme, a folyadékkorlátozás és a gyógyszeradagolás a vesefunkcióhoz igazítva mind ápolói felelősség.","when":["Végstádiumú vesebetegség gondozása","Dializált beteg felvétele bármilyen más okból","A kezelés közötti időszak panaszai: fáradtság, izomgörcs, viszketés","Az érösszeköttetés vagy a hasi katéter problémája","Kihagyott kezelés utáni állapotromlás"],"examine":["Az érösszeköttetés ellenőrzése: a jellegzetes zúgás tapintása és hallgatása minden műszakban — ennek hiánya elzáródást jelent, és sürgős","A shuntos kar tilalmainak betartása: azon a karon nincs vérnyomásmérés, vérvétel és infúzió","Testsúly mérése: a kezelés előtti és utáni súly különbsége adja meg az eltávolított folyadék mennyiségét","Folyadékállapot: ödéma, nyaki vénák, tüdőpangás jelei","Hasi katéternél a kilépési nyílás állapota és a lecsapolt folyadék tisztasága","Vérnyomás mindkét helyzetben, mert a kezelés utáni vérnyomásesés gyakori"],"labs":"A kezelés előtti kálium a legfontosabb érték — a kimaradt kezelés utáni magas kálium életveszélyes. Emellett vesefunkció, nátrium, kalcium, foszfát, mellékpajzsmirigy-hormon, vérkép, vasháztartás és gyulladásos értékek. A vérvétel a shunt nélküli karból történik.","ekg":"Magas káliumszint gyanújánál azonnal. A dializált betegeknél a ritmuszavar és a hirtelen szívhalál kockázata magas, különösen a leghosszabb kezelésmentes időszak végén.","imaging":"Mellkasröntgen folyadéktúlterhelés gyanújánál. Az érösszeköttetés vizsgálata elzáródás gyanújánál. Hasi forma esetén a hashártyagyulladás kórisméje a lecsapolt folyadék vizsgálatán alapul, nem képalkotáson.","scores":"A NEWS2 az állapotromlás követésére. Tápláltsági szűrés rendszeresen: a dializált betegek jelentős része alultáplált, és ez rontja a túlélést.","red_flags":["Magas káliumszint, különösen kimaradt kezelés után — azonnali ellátás","Az érösszeköttetés zúgásának hiánya — sürgős, mert az elzáródás órák alatt véglegessé válik","Nehézlégzés, felfekvő testhelyzet kényszere — folyadéktúlterhelés, tüdőödéma","Zavaros lecsapolt folyadék hasi forma esetén — hashártyagyulladás","Láz, hidegrázás — a katéterrel összefüggő véráramfertőzés gyors romlást okoz","Mellkasi fájdalom, ritmuszavar","Vérzés az érösszeköttetésből — nyomókötés és azonnali segítség"],"apn_focus":["A shuntos kar védelme: nincs rajta vérnyomásmérés, vérvétel, infúzió és szorító ruha — ezt a beteg ágya fölött jelölni kell, mert a hiba jellemzően más osztályon történik","Az érösszeköttetés zúgásának ellenőrzése műszakonként, és az eredmény dokumentálása","A testsúly pontos mérése ugyanazon a mérlegen, azonos körülmények között: a folyadékeltávolítás mennyiségét ez határozza meg","A gyógyszerek adagolása a vesefunkcióhoz igazítva, és a dialízis által eltávolított szerek pótlásának ismerete — ez gyakori hibaforrás a nem dialízis szakmájú osztályokon","A folyadék- és káliumkorlátozás értelmének elmagyarázása: a betegek nagy része a szabályt ismeri, az okát nem, és ettől nehezebben tartja be","A kezelés kihagyásának következményei: a hétvégi hosszabb szünet a legkockázatosabb időszak","A viszketés, az izomgörcs és a fáradtság kezelése: ezek rontják a legjobban az életminőséget, és kezelhetők"],"treatment":["A rendszeres kezelés biztosítása és az elmaradás megelőzése","A folyadék- és sóbevitel korlátozása","A foszfátkötő szerek étkezéssel való bevételének megtanítása — az időzítés dönti el a hatásosságot","A vérszegénység kezelése","Az érösszeköttetés gondozása és védelme","A hasi forma esetén a steril technika oktatása és ellenőrzése","A szövődmények kezelése: hashártyagyulladás, katéterfertőzés, kezelés alatti vérnyomásesés"],"followup":["Rendszeres laborellenőrzés a kezelési terv szerint","A tápláltsági állapot szűrése és támogatása","Az érösszeköttetés rendszeres ellenőrzése","Az átültetésre való alkalmasság rendszeres újraértékelése","Oltási állapot követése","Lelki támogatás és az életminőség kérdéseinek felvetése — a dialízis az élet minden területét érinti"],"source_name":"KDIGO irányelv a krónikus vesebetegség értékeléséről és kezeléséről","source_url":"https://kdigo.org/guidelines/ckd-evaluation-and-management/","version":"2024","updated":"2026-09-22","evidence":"Az érösszeköttetés védelme és a rendszeres ellenőrzés a hozzáférés élettartamát bizonyítottan meghosszabbítja. A kimaradt kezelés utáni magas kálium a dializált betegek egyik vezető sürgősségi oka."}'::jsonb,
     '{"Vesepótló kezelés (dialízis) gondozása","dialízis","művese","hemodialízis","peritoneális dialízis","vesepótló kezelés"}'::text[]),
    ('vesetranszplantalt', 'Veseátültetett beteg gondozása', '{"vesetranszplantáció","veseátültetés","graft","immunszuppresszió"}'::text[], 'Tx',
     '{"news2"}'::text[], '{"krea","egfr","uprot","k","na","ca","hb","wbc","crp","gluk"}'::text[], '{}'::text[],
     '{"transzplantáció","veseátültetés","immunszuppresszió","kilökődés"}'::text[], '{"brief_what":"Az átültetett vesével élő beteg élethosszig tartó gondozása. A beültetett vese működését immunrendszert gátló gyógyszerek tartják fenn, amelyek egyensúlyt kívánnak a kilökődés és a fertőzés kockázata között.","brief_why":"Az átültetés nem gyógyulás, hanem másfajta betegség: a beteg gyógyszerszedése egész életen át kötelező, és a kihagyott adag kilökődéshez vezethet. Az ápolói munkában két dolog a legfontosabb: az adherencia támogatása és a fertőzés korai felismerése, mert a szokásos gyulladásos jelek az immunszuppresszió mellett tompultak.","when":["Rendszeres gondozási vizit","Bármilyen panasszal jelentkező átültetett beteg","Emelkedő kreatinin","Láz vagy fertőzésre utaló tünet","Új gyógyszer indítása — az interakciók kockázata magas","Csökkenő vizeletmennyiség vagy a beültetett vese tájékának fájdalma"],"examine":["Vérnyomás és testsúly minden vizitnél","A beültetett vese tájékának tapintása: érzékenység kilökődésre utalhat","Vizeletmennyiség","Fertőzés jeleinek keresése — az immunszuppresszió mellett a láz hiányozhat, és a hasi vagy mellkasi tünet lehet az egyetlen jel","Bőrvizsgálat: az immunszuppresszió mellett a bőrdaganatok kockázata sokszorosára nő","A szájnyálkahártya és a foghús állapota: egyes szerek fogínyduzzanatot okoznak","A gyógyszerszedés tényleges menetének végigkérdezése, nem csak a lista felolvasása"],"labs":"Kreatinin és szűrési érték rendszeresen — az emelkedés a kilökődés legkorábbi jele, gyakran tünet nélkül. Az immunszuppresszív szerek vérszintje a kezelési terv szerint. Emellett vérkép, ionok, vércukor, fehérjevizelés és a fertőzések célzott vizsgálata. A vírusos fertőzések szűrése a gondozás része.","ekg":"Nem rutinszerű; ioneltérés vagy szívpanasz esetén indokolt.","imaging":"A beültetett vese ultrahangja működészavar esetén: elzáródás, folyadékgyülem és keringési zavar kizárására. A kilökődés kórisméje biopsziával történik.","scores":"Külön pontozó nincs. A szűrési érték változásának üteme a legfontosabb mutató.","red_flags":["Emelkedő kreatinin — kilökődés gyanúja, sürgős transzplantációs központ","Láz vagy akár enyhe, elhúzódó fertőzésgyanú — az immunszuppresszió mellett a súlyos fertőzés szegényes tünetekkel jár","Csökkenő vizeletmennyiség","A beültetett vese tájékának fájdalma, duzzanata","Kihagyott gyógyszeradagok","Új gyógyszer vagy gyógynövény indítása — az immunszuppresszív szerek vérszintjét jelentősen befolyásolhatják","Gyorsan növekvő, nem gyógyuló bőrelváltozás"],"apn_focus":["Az adherencia a gondozás legfontosabb kérdése: az elmaradt adagok a késői graftvesztés vezető oka, és a beteg ritkán vallja be magától — konkrét, nem szemrehányó kérdésekkel érdemes közelíteni","Minden új gyógyszer és gyógynövény jelentése a transzplantációs központnak: több gyakori szer és étrend-kiegészítő megemeli vagy leejti az immunszuppresszív szer vérszintjét","A vérszint-ellenőrzés előtti reggeli adag bevételének rendje — a helytelen időzítés értelmezhetetlen eredményt ad","A fertőzésjelek tompultságának ismertetése: az átültetett betegnél a mérsékelt panasz is súlyos fertőzést jelenthet","Napfényvédelem és rendszeres bőrellenőrzés oktatása — a bőrdaganat kockázata jelentősen emelkedett","Élelmiszerbiztonsági tanácsok: nyers és pasztőrözetlen élelmiszerek kerülése","Oltási rend ismerete: az élő kórokozót tartalmazó oltások ellenjavalltak","Fogamzásgátlás és a tervezett terhesség előzetes megbeszélése"],"treatment":["Az immunszuppresszív kezelés folyamatos fenntartása, a központ által meghatározott rend szerint","A kilökődés kezelése a transzplantációs központban","A szövődmények kezelése: magas vérnyomás, cukorbetegség, csontritkulás, vérszegénység","A fertőzések megelőzése és korai kezelése","A szív- és érrendszeri kockázat kezelése — ez a leggyakoribb halálok működő vesével"],"followup":["Rendszeres laborellenőrzés a központ által megadott ütemben","Vérnyomás és testsúly otthoni követése","Daganatszűrés, kiemelten a bőrt illetően","Oltási állapot karbantartása","A csontanyagcsere és a vércukor követése","Az életmód és a visszatérés a munkába: a gondozás célja nem a védettség, hanem a teljes élet"],"source_name":"KDIGO irányelv a veseátültetett beteg gondozásáról","source_url":"https://kdigo.org/guidelines/transplant-recipient/","version":"2009 (a jelöltek értékeléséről szóló irányelv 2020)","updated":"2026-09-22","evidence":"A gyógyszerszedés elmaradása a késői graftvesztés egyik vezető oka. A szív- és érrendszeri betegség a működő vesével élő átültetett betegek leggyakoribb halálokoza. A bőrdaganatok fokozott kockázata miatt a rendszeres bőrellenőrzés ajánlott."}'::jsonb,
     '{"Veseátültetett beteg gondozása","vesetranszplantáció","veseátültetés","graft","immunszuppresszió"}'::text[]),
    ('vizelet-inkontinencia', 'Vizelet-inkontinencia', '{"vizeletcsepegés","akaratlan vizeletvesztés","stressz inkontinencia","sürgősségi inkontinencia"}'::text[], 'Inkontinencia',
     '{"barthel","morse"}'::text[], '{"used","krea","egfr","gluk"}'::text[], '{}'::text[],
     '{"inkontinencia","vizeletvesztés","hólyagtréning","gátizom"}'::text[], '{"brief_what":"Akaratlan vizeletvesztés. Fő formái: a hasűri nyomás emelkedésére jelentkező stresszes forma, a hirtelen, elviselhetetlen ingerrel járó sürgősségi forma, és a kettő keveréke.","brief_why":"Rendkívül gyakori, és a betegek nagy része nem hozza szóba — szégyellik, vagy az öregedés velejárójának tartják. Pedig az inkontinencia kezelhető, és nem kezelve elszigetelődéshez, bőrkárosodáshoz, eleséshez és idő előtti intézményi elhelyezéshez vezet. Az első kérdés az ápolótól gyakran a beteg egyetlen esélye arra, hogy a téma felmerüljön.","when":["A beteg maga jelzi — ez a ritkább eset","Betétet, pelenkát használ","Ismétlődő húgyúti fertőzés","Gátizom körüli bőrpír, bőrkárosodás","Éjszakai vizelés miatti elesés","Szűkülő életvitel: a beteg kerüli a hosszabb utazást, a társaságot","Szülés, prosztataműtét vagy medencei beavatkozás után"],"examine":["A vizeletvesztés körülményeinek tisztázása: köhögésre, emelésre jön-e, vagy hirtelen inger előzi meg — ez dönti el a formát és a kezelést","Vizelési napló javaslata: néhány nap alatt többet mond, mint bármely egyszeri kérdés","A gátizom körüli bőr állapota","Hasi tapintás: telt hólyag a túlfolyásos forma jele","A gyógyszerlista átnézése: vízhajtó, nyugtató, egyes vérnyomáscsökkentők ronthatják","Mozgásképesség és az illemhely elérhetősége — az akadály néha nem a hólyagban van","Székrekedés keresése: a telt végbél rontja a hólyagműködést","Szellemi állapot felmérése, ha az együttműködés kérdéses"],"labs":"Vizeletvizsgálat a fertőzés kizárására — a kezeletlen fertőzés átmeneti inkontinenciát okoz. Vércukor: a magas vércukor fokozott vizeletürítéssel jár. Vesefunkció, ha elzáródás merül fel.","ekg":"Nincs szerepe.","imaging":"Hólyag-ultrahang a vizelés utáni maradék meghatározására: a jelentős maradék más kezelési irányt jelent. További képalkotás csak célzottan.","scores":"A vizelési napló a legfontosabb eszköz. Idős betegnél az önellátás és az esési kockázat felmérése is a kép része, mert az éjszakai sietés eleséshez vezet.","red_flags":["Vérvizelés — daganat irányába kivizsgálás","Fájdalom vagy ismétlődő fertőzés","Hirtelen kialakult inkontinencia neurológiai tünetekkel — gerincvelői érintettség, sürgős","Jelentős vizelés utáni maradék vagy telt hólyag","Kismedencei besüllyedés előrehaladott formája","Korábbi medencei sugárkezelés vagy műtét utáni új tünet"],"apn_focus":["A téma felvetése: a beteg jellemzően nem hozza szóba — a közvetlen, tárgyilagos kérdés a gondozás első lépése","A vizelési napló megtanítása: mikor, mennyit iszik, mikor és mennyit vizel, mikor vesztett vizeletet — ez adja a kezelés alapját","A gátizomtorna helyes technikájának megtanítása: a legtöbb beteg rosszul végzi, és a hibás gyakorlat nem hat — az ellenőrzött oktatás bizonyítottan hatásos, műtét nélkül is","A folyadékbevitel rendezése: a betegek gyakran radikálisan csökkentik, ami töményebb vizeletet és több hólyagingert okoz — a megoldás az időzítés, nem a megvonás","Az izgató italok — koffein, alkohol, szénsavas ital — szerepének ismertetése","A bőr védelme: a nedvesség okozta bőrkárosodás megelőzése a betét helyes megválasztásával és a bőr ápolásával","A betét és a pelenka nem kezelés, hanem segédeszköz: a beteg számára ezt ki kell mondani, mert sokan itt megállnak","Székrekedés rendezése — egyszerű és gyakran hatásos lépés"],"treatment":["Életmódbeli lépések: testsúlycsökkentés, folyadékrend, izgató italok csökkentése, székrekedés kezelése","Gátizomtorna ellenőrzött oktatással — az első választás a stresszes formánál","Hólyagtréning a sürgősségi formánál: a vizelési időközök fokozatos növelése","Gyógyszeres kezelés a sürgősségi formánál, az idős betegnél a szellemi működésre gyakorolt hatás mérlegelésével","Helyi ösztrogénkezelés a hüvelyszárazság okozta panaszoknál","Műtéti megoldás, ha a nem műtéti kezelés nem elég","Katéter csak végső megoldásként — az állandó katéter fertőzést és további károsodást okoz"],"followup":["A vizelési napló ismételt átnézése a kezelés hatásának megítélésére","A gátizomtorna technikájának ellenőrzése — a hatás a helyes kivitelen múlik","A bőr állapotának követése","Az életminőség változásának megbeszélése","Szakellátásba irányítás, ha a kezdeti kezelés három hónap alatt nem hoz javulást"],"source_name":"Európai Urológiai Társaság irányelve a vizelet-inkontinencia ellátásáról","source_url":"https://uroweb.org/guidelines","version":"2025","updated":"2026-09-22","evidence":"Az ellenőrzött oktatással végzett gátizomtorna hatásossága a stresszes forma kezelésében erősen alátámasztott, és a műtétet megelőző első lépés. Az állandó katéter inkontinencia kezelésére nem javasolt."}'::jsonb,
     '{"Vizelet-inkontinencia","vizeletcsepegés","akaratlan vizeletvesztés","stressz inkontinencia","sürgősségi inkontinencia"}'::text[]),
    ('tunetmentes-bacteriuria', 'Tünetmentes bacteriuria', '{"tünetmentes baktériumürítés","pozitív vizelettenyésztés panasz nélkül","aszimptomatikus bacteriuria"}'::text[], 'ASB',
     '{"news2"}'::text[], '{"used","crp","wbc","krea","egfr"}'::text[], '{}'::text[],
     '{"bacteriuria","vizelettenyésztés","antibiotikum","túlkezelés"}'::text[], '{"brief_what":"Baktérium kimutatható a vizeletben, de a betegnek nincsenek húgyúti panaszai. Nem fertőzés, hanem lelet — a húgyutak baktériumokkal való benépesülése.","brief_why":"Ez a platform egyik legfontosabb „mit ne tegyünk\" adatlapja. A tünetmentes bacteriuria antibiotikumos kezelése a kórházi antibiotikum-felhasználás egyik legnagyobb indokolatlan tétele: nem előzi meg a fertőzést, viszont rezisztens baktériumokat tenyészt ki, és bélgyulladást okozhat. A hiba jellemzően ott kezdődik, hogy a vizeletet ok nélkül tenyésztésre küldik.","when":["Rutinszerűen levett vizelettenyésztés pozitív eredménye panasz nélkül","Zavaros vagy szagos vizelet mint egyetlen ok a vizsgálatra","Idős beteg zavartsága esetén automatikusan kért vizelettenyésztés","Tartós katéter melletti pozitív tenyésztés","Terhesgondozás szűrővizsgálata","Urológiai beavatkozás előtti kivizsgálás"],"examine":["A valódi húgyúti panaszok célzott kikérdezése: vizeléskori égő érzés, gyakori vizelési inger, alhasi fájdalom, ágyéki fájdalom, láz","Ha ezek hiányoznak, a lelet nem fertőzés — ez a vizsgálat lényege","Idős, zavart betegnél a zavartság más okainak keresése: kiszáradás, gyógyszer, fájdalom, székrekedés, tüdőgyulladás — a bacteriuria ritkán az igazi ok","A vizelet szagának és színének megítélése: ez önmagában nem jelez fertőzést","Testhőmérséklet és általános állapot"],"labs":"A kérdés nem az, hogy mi jött ki, hanem hogy miért vették le. Tünetmentes betegnél a vizelettenyésztés általában nem indokolt — kivétel a terhesség és bizonyos urológiai beavatkozások előtti szűrés. A vizeletcsík fehérvérsejt-jelzése és a nitritpozitivitás tünetek nélkül szintén nem jelent kezelendő fertőzést.","ekg":"Nincs szerepe.","imaging":"Nincs szerepe a tünetmentes formában.","scores":"A NEWS2 segít elkülöníteni: a valóban fertőzött beteg általános állapota romlik, a tünetmentes bacteriuriáé nem.","red_flags":["Láz, hidegrázás, ágyéki fájdalom — ez már nem tünetmentes bacteriuria, hanem fertőzés","Terhesség — itt a tünetmentes forma is kezelendő, mert vesemedence-gyulladáshoz és koraszüléshez vezethet","Nyálkahártya-sérüléssel járó urológiai beavatkozás előtt — itt szintén kezelendő","Romló általános állapot, keringési instabilitás","Friss veseátültetés utáni korai időszak — egyéni mérlegelés"],"apn_focus":["A legfontosabb szabály: tünetmentes betegtől ne kérjünk vizelettenyésztést, mert a pozitív eredmény kezelési kényszert szül","A zavaros, szagos vizelet nem indok a tenyésztésre: jellemzően a töményebb vizelet vagy a táplálkozás magyarázza","Az idős beteg zavartságánál a bacteriuria a legkényelmesebb, de ritkán a helyes magyarázat — a valódi ok keresése az ápolói felmérés feladata","A katéteres betegnél gyakorlatilag mindig kimutatható baktérium: a tenyésztés csak fertőzésre utaló tünet mellett indokolt","A beteg és a hozzátartozó tájékoztatása, hogy az antibiotikum elmaradása itt nem mulasztás, hanem a helyes döntés","A terhesség mint kivétel ismerete: a terhesgondozásban a szűrés és a kezelés indokolt","A dokumentáció pontossága: a „húgyúti fertőzés\" címke évekre rátapad a betegre, és újabb fölösleges kezeléseket szül"],"treatment":["Tünetmentes betegnél antibiotikum nem indokolt — ez a kezelés","Kivétel: terhesség, valamint a húgyúti nyálkahártya sérülésével járó beavatkozás előtt","A folyadékbevitel rendezése","Katéteres betegnél a katéter szükségességének felülvizsgálata: a legjobb megelőzés a katéter eltávolítása","Ha panasz jelentkezik, a beteget húgyúti fertőzésként kell értékelni és aszerint kezelni"],"followup":["Ismételt tenyésztés tünetmentes betegnél nem szükséges","Terhességben a kezelés után ellenőrző tenyésztés","A panaszok megjelenésének figyelése és a beteg tájékoztatása arról, mikor kell jelentkeznie","A katéter szükségességének rendszeres újraértékelése"],"source_name":"Európai Urológiai Társaság irányelve a húgyúti fertőzésekről","source_url":"https://uroweb.org/guidelines/urological-infections","version":"2025","updated":"2026-09-22","evidence":"A tünetmentes bacteriuria kezelése nem csökkenti a későbbi fertőzések számát, viszont növeli a rezisztencia és a mellékhatások kockázatát — a kezelés elhagyása erős ajánlás. Kivétel a terhesség és a nyálkahártya-sérüléssel járó urológiai beavatkozás."}'::jsonb,
     '{"Tünetmentes bacteriuria","tünetmentes baktériumürítés","pozitív vizelettenyésztés panasz nélkül","aszimptomatikus bacteriuria"}'::text[]),
    ('nefrotoxikus-vesekarosodas', 'Gyógyszer és kontrasztanyag okozta vesekárosodás', '{"nefrotoxicitás","kontrasztanyag okozta vesekárosodás","gyógyszeres vesekárosodás"}'::text[], 'Nefrotoxicitás',
     '{"news2"}'::text[], '{"krea","egfr","k","na","urea","ck","used"}'::text[], '{"hyperk"}'::text[],
     '{"nefrotoxikus","kontrasztanyag","vesekárosodás","gyógyszerbiztonság"}'::text[], '{"brief_what":"A vesefunkció romlása gyógyszer vagy röntgenkontrasztanyag hatására. Az ok lehet a vese keringésének csökkenése, a vesecsatornák közvetlen károsodása vagy immunológiai reakció.","brief_why":"A kórházban kialakuló akut vesekárosodás jelentős része megelőzhető lenne, és a leggyakoribb kiváltók mindennapos, ártalmatlannak tartott szerek. A klasszikus hármas — vízhajtó, vérnyomáscsökkentő vese-védő szer és gyulladáscsökkentő — együtt szedve kiszáradás vagy heveny betegség idején gyors károsodást okoz. Ennek felismerése és megelőzése nagyrészt ápolói feladat.","when":["Romló vesefunkció kórházi kezelés alatt","Kontrasztanyagos vizsgálat előtti kockázatbecslés","Heveny betegség — hányás, hasmenés, láz — meglévő gyógyszerszedés mellett","Új gyógyszer indítása után jelentkező vizeletmennyiség-csökkenés","Idős, vesebeteg vagy szívelégtelen beteg kivizsgálása","Több vesekárosító szer együttes szedése"],"examine":["A teljes gyógyszerlista átnézése, beleértve a vény nélkül kapható szereket és az étrend-kiegészítőket — a fájdalomcsillapítók nagy részét a beteg nem tekinti gyógyszernek","Folyadékállapot felmérése: kiszáradás, bőrturgor, nyálkahártyák, vérnyomás","Vizeletmennyiség mérése és dokumentálása","Testsúly követése","A heveny betegség jeleinek keresése: ez az az állapot, amelyben a szokásos gyógyszerek veszélyessé válnak","Bőrtünet, láz, ízületi panasz — immunológiai eredetű vesecsatorna-gyulladás irányába"],"labs":"Kreatinin és szűrési érték a kiindulási értékhez viszonyítva — az abszolút szám önmagában keveset mond, a változás a lényeg. Ionok, kiemelten a kálium. Vizeletüledék: a fehérvérsejtek jelenléte fertőzés nélkül immunológiai eredetre utalhat. Izomenzim, ha izomszétesés merül fel. Kontrasztanyagos vizsgálat előtt és után a vesefunkció ellenőrzése a kockázatos betegeknél.","ekg":"Magas káliumszint gyanújánál indokolt.","imaging":"Vese-ultrahang az elzáródás kizárására minden tisztázatlan vesefunkció-romlásnál. A kontrasztanyagos vizsgálat indikációját a kockázattal együtt kell mérlegelni — a halasztás nem mindig a biztonságosabb döntés, mert az elmaradt kórisme is árt.","scores":"A vesekárosodás súlyosságát a kreatinin emelkedése és a vizeletmennyiség csökkenése alapján osztályozzuk. A NEWS2 az általános állapot követésére alkalmas.","red_flags":["Csökkenő vizeletmennyiség","Gyorsan emelkedő kreatinin","Magas káliumszint EKG-eltéréssel","Folyadéktúlterhelés, nehézlégzés","Több vesekárosító szer együttes szedése heveny betegség alatt","Bőrkiütés, láz és eozinofília a gyógyszerindítás után — immunológiai vesecsatorna-gyulladás","Sötét, kólaszínű vizelet izomfájdalommal — izomszétesés"],"apn_focus":["A betegnapok szabályának megtanítása: hányás, hasmenés vagy láz esetén bizonyos gyógyszerek átmeneti szüneteltetése — ez az egyik legjobban megtérülő betegoktatási elem a vesebetegek gondozásában","A gyulladáscsökkentők kockázatának ismertetése: vény nélkül kaphatók, a beteg nem tartja gyógyszernek, és vesebeteg számára a leggyakoribb elkerülhető károsodás forrása","A vizeletmennyiség mérése és dokumentálása minden kockázatos betegnél — a csökkenés gyakran megelőzi a laboreltérést","A gyógyszeradagok ellenőrzése a szűrési érték szerint, különösen a vesén át ürülő szereknél","A folyadékállapot rendezése kontrasztanyagos vizsgálat előtt a kockázatos betegeknél — ez a bizonyítottan hatásos megelőzés","A kiindulási kreatinin ismerete: enélkül nem lehet megítélni, romlott-e a vesefunkció","A gyógyszerelés és a laborváltozás időbeli összefüggésének rögzítése — ez teszi felismerhetővé az okot"],"treatment":["A kiváltó szer elhagyása vagy adagcsökkentése — ez az első és legfontosabb lépés","A folyadékállapot rendezése","A további vesekárosító szerek kerülése","Az adagok igazítása az aktuális vesefunkcióhoz","Immunológiai eredetű vesecsatorna-gyulladásnál a kiváltó szer azonnali elhagyása, szükség esetén gyulladáscsökkentő kezelés","Vesepótló kezelés súlyos esetben"],"followup":["A vesefunkció ismételt ellenőrzése a kiváltó elhagyása után — a javulás hetekig tarthat","A lezajlott akut károsodás nem tér vissza nyom nélkül: a krónikus vesebetegség kockázata utána tartósan emelkedett, ezért követés szükséges","A gyógyszerlista végleges rendezése és a kiváltó szer rögzítése a dokumentációban","A betegnapok szabályának ismételt átbeszélése","A vérnyomás- és vesevédő kezelés újraindításának mérlegelése: ezek elhagyása hosszú távon szintén árt"],"source_name":"KDIGO irányelv az akut vesekárosodásról","source_url":"https://kdigo.org/guidelines/acute-kidney-injury/","version":"2012 — a 2026-os frissítés nyilvános véleményezés alatt","updated":"2026-09-22","evidence":"A kiváltó szer elhagyása és a folyadékállapot rendezése a kezelés alapja. A kontrasztanyag okozta vesekárosodás kockázatát az újabb vizsgálatok a korábbi becslésnél kisebbnek találták, ezért az indokolt vizsgálat halasztása nem automatikus döntés. Az irányelv 2026-os frissítése nyilvános véleményezési szakaszban van, ezért a hivatkozás a hatályos változatra mutat."}'::jsonb,
     '{"Gyógyszer és kontrasztanyag okozta vesekárosodás","nefrotoxicitás","kontrasztanyag okozta vesekárosodás","gyógyszeres vesekárosodás"}'::text[]),
    ('hydronephrosis', 'Húgyúti elzáródás (hydronephrosis)', '{"vesemedence-tágulat","obstruktív uropathia","húgyúti obstrukció","pangásos vese"}'::text[], 'Elzáródás',
